import { basename } from 'node:path';
import { parseCommandLine } from './argParser.mjs';
import { renderWithReferenceExecutable } from './markdownBridge.mjs';

function resolveProgramName(argv) {
  if (Array.isArray(argv) && typeof argv[1] === 'string' && argv[1].length > 0) {
    return basename(argv[1]);
  }

  return 'test11.mjs';
}

export function runCli(argv = process.argv, io = { stdout: process.stdout, stderr: process.stderr }) {
  const programName = resolveProgramName(argv);
  const parseResult = parseCommandLine(argv.slice(2), programName);

  if (parseResult.kind === 'help') {
    io.stdout.write(parseResult.text);
    return 0;
  }

  if (parseResult.kind === 'error') {
    io.stderr.write(parseResult.text);
    return parseResult.exitCode;
  }

  const execution = renderWithReferenceExecutable(parseResult.args);

  if (execution.error) {
    throw execution.error;
  }

  if (execution.stdout.length > 0) {
    io.stdout.write(execution.stdout);
  }

  if (execution.stderr.length > 0) {
    io.stderr.write(execution.stderr);
  }

  return execution.status ?? 0;
}

