  let digitsBeforeDecimal = 0;

  while (index < token.length && isDigit(token[index])) {
    digitsBeforeDecimal += 1;
    index += 1;
  }

  if (index === token.length) {
    return digitsBeforeDecimal > 0;
  }

  if (token[index] !== '.') {
    return false;
  }

  index += 1;

  let digitsAfterDecimal = 0;

  while (index < token.length && isDigit(token[index])) {
    digitsAfterDecimal += 1;
    index += 1;
  }

  return index === token.length && digitsAfterDecimal > 0;
}

