  const separatorIndex = token.indexOf('=');

  if (separatorIndex === -1) {
    return {
      name: token,
      hasInlineValue: false,
      value: '',
    };
  }

  return {
    name: token.slice(0, separatorIndex),
    hasInlineValue: true,
    value: token.slice(separatorIndex + 1),
  };
}

