  if (token.length < 2 || token[0] !== '-' || token[1] !== 'h' || token.startsWith('--')) {
    return null;
  }

  if (token.length > 2 && token[2] === '=') {
    return {
      kind: 'error',
      value: token.slice(3),
    };
  }

  return {
    kind: 'help',
  };
}

