    kind: 'help',
    text: buildHelpText(programName),
  };
}

function buildErrorResult(programName, message) {
  return {
    kind: 'error',
    text: buildErrorText(programName, message),
    exitCode: 2,
  };
}

export function parseCommandLine(argumentTokens, programName) {
